---@class BehaviorTree
local BehaviorTree = Class("BehaviorTree")

function BehaviorTree:__init()
    --- 行为树应该多久更新一次。updatePeriod为0.2将使行为树每秒更新5次
    self._updatePeriod = nil
    
    ---上下文应包含运行树所需的所有数据
    self._context = nil
    
    ---根节点
    self._root    = nil
    
    ---自定义tick
    self._customTickCb = nil
    
end

function BehaviorTree:__delete()
    
end

function BehaviorTree:Init(context, rootNode, updatePeriod, customTickCb)
    self._context      = context
    self._root         = rootNode
    updatePeriod       = updatePeriod or 0.2
    self._updatePeriod = updatePeriod > 0 and Yielders.GetWaitForSeconds(updatePeriod) or Yielders.EndOfFrame
    self._customTickCb = customTickCb
end

function BehaviorTree:Tick()
    if self._customTickCb then
        if self._customTickCb() then
            self._root:Tick(self._context)
        end
        return
    end
    
    cs_coroutine.yield_return(self._updatePeriod)
    self._root:Tick(self._context)
    
end

return BehaviorTree
 